import sys
import math

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998244353
            self.fact = []
            self.inv_fact = []

        def fInv(self, n):
            # Precompute factorials and inverse factorials up to n
            self.fact = [1] * (n + 1)
            for i in range(1, n + 1):
                self.fact[i] = (self.fact[i - 1] * i) % self.mod
            self.inv_fact = [1] * (n + 1)
            self.inv_fact[n] = pow(self.fact[n], self.mod - 2, self.mod)
            for i in range(n - 1, -1, -1):
                self.inv_fact[i] = (self.inv_fact[i + 1] * (i + 1)) % self.mod

        def mult(self, a, b):
            return (a * b) % self.mod

        def add(self, a, b):
            return (a + b) % self.mod

        def subtract(self, a, b):
            return (a - b) % self.mod

        def ncr(self, n, r):
            if r < 0 or r > n:
                return 0
            return (self.fact[n] * self.inv_fact[r] % self.mod) * self.inv_fact[n - r] % self.mod

        def smallInv(self, n):
            # Modular inverse using Fermat's little theorem
            return pow(n, self.mod - 2, self.mod)

def main():
    input_line = sys.stdin.readline().strip()
    tokens = input_line.split()
    n = int(tokens[0])
    m = int(tokens[1])

    mod = NumberTheory.Mod998()
    max_value = n + m + 10  # buffer for safety
    mod.fInv(max_value)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = (p * (n - i)) % mod.mod
        p = (p * mod.smallInv(n + m - i)) % mod.mod
        phaseSize = (phaseSize + p) % mod.mod
        i += 1
        if i > n + m:
            break

    answer = 0
    for k in range(1, n + 1):
        numPhases = (m + k) * mod.smallInv(k) % mod.mod
        e = (numPhases * phaseSize) % mod.mod
        term = (mod.ncr(n, k) * e) % mod.mod
        if k % 2 == 1:
            answer = (answer + term) % mod.mod
        else:
            answer = (answer - term) % mod.mod

    print(answer)

if __name__ == "__main__":
    main()

